import {plotAxes,buildPlotData,axisDomain,scaleValue,axisTicks,plotCsv,normalizePlotOptions,countedOptions} from './actuator-analysis.js?v=morph-20261109';
import {getLanguage,t,csvInLanguage} from './i18n.js?v=morph-20261109';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const palette=['#287c72','#d07d3e','#596bc4','#c35d81','#7d8a31','#785cac','#248dab','#af653b','#4b8e59','#b94449','#6c7c8a','#9b8b64','#697fc5','#d08183'];
const num=n=>n===0?'0':Math.abs(n)<.001||Math.abs(n)>=100000?n.toExponential(1):Number(n.toPrecision(4)).toLocaleString('en-US',{maximumFractionDigits:5});
const label=k=>t(plotAxes[k][0])+' ('+plotAxes[k][1]+')';
function download(contents,type,name){const u=URL.createObjectURL(new Blob([contents],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
export function createActuatorPlot({products,sources,onFavorite,onOpen,isFavorite,notify}){
 let options;try{const saved=JSON.parse(localStorage.getItem('atlas-actuator-plot')||'{}');if(saved&&saved.layer==='module'&&!saved.scopeVersion)saved.layer='output';options=normalizePlotOptions(saved);}catch{options=normalizePlotOptions();}
 let records=[],plot,selectedId=null,root=null;
 const groups={};for(const key of ['brand','category','encoder'])groups[key]=countedOptions(products,key).map(x=>x.value);
 const color=p=>palette[Math.max(0,groups[options.colorBy].indexOf(p[options.colorBy]))%palette.length];
 function save(){try{localStorage.setItem('atlas-actuator-plot',JSON.stringify({...options,scopeVersion:2}));}catch{}}
 function selectOptions(key){return Object.entries(plotAxes).map(([id,[name,unit]])=>`<option value="${id}" ${options[key]===id?'selected':''}>${esc(t(name))} (${esc(unit)})</option>`).join('');}
 function controls(){return `<div class="plot-head"><div><p class="eyebrow">ACTUATOR PERFORMANCE</p><h3>${esc(t('性能对比图'))}</h3><p>${esc(t('每个点代表一个具体型号 / 电压配置。'))}</p></div><div class="plot-exports"><button type="button" class="button button-outline" data-plot-export="svg">${esc(t('下载图 SVG'))}</button><button type="button" class="button button-outline" data-plot-export="csv">${esc(t('下载坐标 CSV'))}</button></div></div><div class="plot-controls"><label>${esc(t('横轴'))}<select id="plotXAxis" data-plot-option="x">${selectOptions('x')}</select></label><label>${esc(t('纵轴'))}<select id="plotYAxis" data-plot-option="y">${selectOptions('y')}</select></label><button type="button" class="plot-swap" data-plot-swap aria-label="${esc(t('交换横纵轴'))}" title="${esc(t('交换横纵轴'))}">⇄</button><label>${esc(t('横轴刻度'))}<select id="plotXScale" data-plot-option="xScale"><option value="linear" ${options.xScale==='linear'?'selected':''}>${esc(t('线性'))}</option><option value="log" ${options.xScale==='log'?'selected':''}>${esc(t('对数'))}</option></select></label><label>${esc(t('纵轴刻度'))}<select id="plotYScale" data-plot-option="yScale"><option value="linear" ${options.yScale==='linear'?'selected':''}>${esc(t('线性'))}</option><option value="log" ${options.yScale==='log'?'selected':''}>${esc(t('对数'))}</option></select></label><label>${esc(t('颜色区分'))}<select id="plotColor" data-plot-option="colorBy">${[['brand','品牌'],['category','产品门类'],['encoder','编码器方案']].map(([id,l])=>`<option value="${id}" ${options.colorBy===id?'selected':''}>${esc(t(l))}</option>`).join('')}</select></label><label>${esc(t('绘图对象'))}<select id="plotLayer" data-plot-option="layer">${[['output','驱动模组与减速单元'],['module','完整驱动模组 / 舵机'],['geared','电机＋减速器（外配驱动）'],['motor','电机本体（含无框）'],['all','全部集成层级']].map(([id,l])=>`<option value="${id}" ${options.layer===id?'selected':''}>${esc(t(l))}</option>`).join('')}</select></label><label class="plot-label-choice"><input type="checkbox" data-plot-option="labels" ${options.labels?'checked':''}>${esc(t('显示型号标签'))}</label></div>`;}
 function graph(){
 const W=960,H=570,pad={l:100,r:35,t:50,b:110},xd=axisDomain(plot.points.map(p=>p.x.value),options.xScale),yd=axisDomain(plot.points.map(p=>p.y.value),options.yScale),sx=v=>scaleValue(v,xd,[pad.l,W-pad.r],options.xScale),sy=v=>scaleValue(v,yd,[H-pad.b,pad.t],options.yScale);
 const ticks=axisTicks(xd,options.xScale).map(v=>`<path d="M${sx(v)} ${pad.t}V${H-pad.b}" class="plot-gridline"/><text x="${sx(v)}" y="${H-pad.b+25}" text-anchor="middle" class="plot-tick">${num(v)}</text>`).join('')+axisTicks(yd,options.yScale).map(v=>`<path d="M${pad.l} ${sy(v)}H${W-pad.r}" class="plot-gridline"/><text x="${pad.l-14}" y="${sy(v)+4}" text-anchor="end" class="plot-tick">${num(v)}</text>`).join('');
 return `<svg class="performance-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" role="group" aria-label="${esc(t('电机性能散点图'))}"><title>${esc(t('性能对比图'))} · ${esc(label(options.x))} × ${esc(label(options.y))}</title><desc>${esc(t('缺失坐标的型号不进入图中。点击数据点可查看原始条件。'))}</desc><style>.plot-gridline{stroke:#e5ece7;stroke-width:1}.plot-tick{fill:#7a8b80;font:12px -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}.plot-axis-label{fill:#365b45;font:14px -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}.point-label{fill:#344f40;font:10px -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;paint-order:stroke;stroke:#fff;stroke-width:3px;stroke-linejoin:round}.plot-point{cursor:pointer;outline:none}.plot-point:hover .point-core,.plot-point:focus-visible .point-core{stroke:#203c2a;stroke-width:3}.selected-ring{fill:none;stroke:#294c36;stroke-width:2}.plot-footnote{fill:#87978c;font:11px -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}</style><rect width="${W}" height="${H}" fill="#fff"/>${ticks}<path d="M${pad.l} ${pad.t}V${H-pad.b}H${W-pad.r}" fill="none" stroke="#9cad9f"/><text class="plot-axis-label" x="${(pad.l+W-pad.r)/2}" y="${H-48}" text-anchor="middle">${esc(label(options.x))}</text><text class="plot-axis-label" x="${pad.l}" y="24">${esc(label(options.y))}</text>${plot.points.map(point=>{const x=sx(point.x.value),y=sy(point.y.value),p=point.product;return `<g class="plot-point ${selectedId===p.id?'selected':''}" tabindex="0" role="button" aria-label="${esc(p.model+' · '+label(options.x)+': '+num(point.x.value)+' · '+label(options.y)+': '+num(point.y.value))}" data-plot-point="${esc(p.id)}"><title>${esc(t(p.brand)+' · '+p.model+'\n'+label(options.x)+': '+num(point.x.value)+'\n'+label(options.y)+': '+num(point.y.value))}</title><circle cx="${x}" cy="${y}" r="13" fill="transparent"/>${selectedId===p.id?`<circle class="selected-ring" cx="${x}" cy="${y}" r="9"/>`:''}<circle class="point-core" cx="${x}" cy="${y}" r="5.5" fill="${color(p)}" fill-opacity="${p.integration==='motor'?.35:.85}" stroke="${color(p)}" stroke-width="1.5"/>${options.labels?`<text x="${Math.min(x+10,W-150)}" y="${Math.max(y-9,40)}" class="point-label">${esc(p.model)}</text>`:''}</g>`;}).join('')}<text x="${pad.l}" y="${H-14}" class="plot-footnote">${esc(t('公开资料记录值；工况与额定定义见原始资料。'))}</text></svg>`;
 }
 function legend(){const names=countedOptions(plot.points.map(p=>p.product),options.colorBy);return `<div class="plot-legend" aria-label="${esc(t('颜色图例'))}">${names.map(g=>`<span><i style="background:${palette[groups[options.colorBy].indexOf(g.value)%palette.length]}"></i>${esc(t(g.value))}<small>${g.count}</small></span>`).join('')}</div>`;}
 function metricSources(m){return [...new Set(m.sourceIds)].map(id=>{const s=sources[id];return s?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(id)} ↗</a>`:esc(id);}).join(' · ');}
 function inspect(){const point=plot.points.find(p=>p.id===selectedId);if(!point)return `<p class="plot-inspect-empty">${esc(t('悬停、点击或用键盘选择数据点，查看型号、条件与来源。'))}</p>`;const p=point.product;return `<div class="plot-selected-title"><div><p>${esc(t(p.brand))} · ${esc(t(p.integration==='motor'?'电机本体':p.integration==='geared'?'电机＋减速器':'完整驱动模组'))}</p><h4>${esc(p.model)}</h4></div><div><button type="button" class="button button-outline" data-plot-favorite="${esc(p.id)}">${esc(t(isFavorite(p.id)?'★ 已收藏':'☆ 收藏型号'))}</button><button type="button" class="button button-primary" data-plot-open="${esc(p.id)}">${esc(t('查看详情'))} →</button></div></div><div class="plot-selected-metrics">${['x','y'].map(axis=>{const m=point[axis];return `<div><span>${esc(label(options[axis]))}</span><strong>${m.derived?'≈':esc({'约':'≈','>=':'≥','<=':'≤'}[m.qual]||(['≥','≤','>','<','≈'].includes(m.qual)?m.qual:''))}${num(m.value)}</strong><small>${m.derived?esc(t('由所列扭矩与质量计算；原始条件分别保留。'))+' ':''}${esc(m.conditions.join('；')||t('原文未进一步披露测试条件'))}</small><div class="plot-source-links">${metricSources(m)}</div></div>`;}).join('')}</div>`;}
 function render(target,input){root=target;records=input;plot=buildPlotData(records,options);if(!plot.points.some(p=>p.id===selectedId))selectedId=null;const c=plot.counts;root.innerHTML=controls()+`<div class="plot-summary" aria-live="polite"><span>${esc(t('参与绘图'))} <strong>${c.plotted}</strong> / ${c.input}</span><span>${esc(t('缺少坐标'))} ${c.missing}</span><span>${esc(t('口径外'))} ${c.layer}</span>${c.nonPositive?`<span>${esc(t('对数轴排除非正值'))} ${c.nonPositive}</span>`:''}</div><p class="plot-scope-note">${esc(t(options.layer==='all'?'当前混合电机轴端与模组输出端，不能直接视为同一关节输出口径。':'额定、峰值、堵转分别作图；每项工作条件在点选详情中保留。'))}</p>${plot.points.length?`<div class="plot-scroll">${graph()}</div><p class="plot-swipe-hint">${esc(t('窄屏可左右滑动图表。'))}</p>${legend()}`:`<div class="plot-empty"><h4>${esc(t('当前没有可绘制的数据点'))}</h4><p>${esc(t('请调整坐标指标、绘图对象或筛选范围；未知值不会按零作图。'))}</p></div>`}${plot.points.length?`<label class="plot-model-picker">${esc(t('选择图中型号'))}<select id="plotModel" data-plot-model><option value="">${esc(t('从入图型号中选择'))}</option>${[...plot.points].sort((a,b)=>a.product.model.localeCompare(b.product.model,'en')).map(point=>`<option value="${esc(point.id)}" ${point.id===selectedId?'selected':''}>${esc(point.product.model)} · ${esc(t(point.product.brand))}</option>`).join('')}</select><small>${esc(t('有重合点时，可在这里精确选择型号。'))}</small></label>`:''}<div class="plot-inspector" id="plotInspector">${inspect()}</div><details class="plot-excluded"><summary>${esc(t('查看未进入图中的型号'))} (${c.missing+c.layer+c.nonPositive})</summary>${plot.excluded.length?`<ul>${plot.excluded.map(x=>`<li><strong>${esc(products.find(p=>p.id===x.id)?.model||x.id)}</strong><span>${esc(t({missing:'缺少横轴或纵轴参数',layer:'不属于当前绘图对象',nonPositive:'对数轴不能显示零或负值'}[x.reason]))}</span></li>`).join('')}</ul>`:`<p>${esc(t('当前记录均有可用坐标。'))}</p>`}</details><a class="plot-guide-link" href="docs/comparison.html">${esc(t('收藏与绘图使用说明'))} ↗</a>`;
 root.onchange=e=>{const el=e.target;if(el.hasAttribute('data-plot-model')){select(el.value);return;}const key=el.dataset.plotOption;if(!key)return;options=normalizePlotOptions({...options,[key]:el.type==='checkbox'?el.checked:el.value});save();render(root,records);root.querySelector('[data-plot-option="'+key+'"]')?.focus();};
 root.onclick=e=>{const point=e.target.closest('[data-plot-point]');if(point)return select(point.dataset.plotPoint);const swap=e.target.closest('[data-plot-swap]');if(swap){options={...options,x:options.y,y:options.x,xScale:options.yScale,yScale:options.xScale};save();render(root,records);return;}const open=e.target.closest('[data-plot-open]');if(open)return onOpen(open.dataset.plotOpen);const fav=e.target.closest('[data-plot-favorite]');if(fav){onFavorite(fav.dataset.plotFavorite);return;}const ex=e.target.closest('[data-plot-export]');if(ex)exportPlot(ex.dataset.plotExport);};
 root.onkeydown=e=>{const point=e.target.closest('[data-plot-point]');if(point&&['Enter',' '].includes(e.key)){e.preventDefault();select(point.dataset.plotPoint);}};
 root.onpointerover=e=>{const point=e.target.closest('[data-plot-point]');if(point)select(point.dataset.plotPoint);};root.onfocusin=e=>{const point=e.target.closest('[data-plot-point]');if(point)select(point.dataset.plotPoint);};
 }
 function select(id){if(selectedId===id)return;selectedId=id;const picker=root.querySelector('#plotModel');if(picker)picker.value=id;root.querySelectorAll('[data-plot-point]').forEach(el=>{el.classList.toggle('selected',el.dataset.plotPoint===id);const c=el.querySelector('.point-core');c?.setAttribute('stroke-width',el.dataset.plotPoint===id?'3':'1.5');});const panel=root.querySelector('#plotInspector');if(panel)panel.innerHTML=inspect();}
 function exportPlot(kind){if(!plot.points.length)return notify('当前没有可绘制的数据点');if(kind==='csv')return download(csvInLanguage(plotCsv(plot,sources)),'text/csv;charset=utf-8',getLanguage()==='en'?'Actuator_Performance_Points.csv':'电机性能对比_坐标.csv');const original=root.querySelector('svg.performance-svg'),svg=original.cloneNode(true);const baseHeight=570,legendGroups=countedOptions(plot.points.map(p=>p.product),options.colorBy),extra=Math.ceil(legendGroups.length/3)*24+28;svg.setAttribute('viewBox',`0 0 960 ${baseHeight+extra}`);svg.setAttribute('width','960');svg.setAttribute('height',baseHeight+extra);svg.querySelector('rect').setAttribute('height',baseHeight+extra);svg.insertAdjacentHTML('beforeend',legendGroups.map((g,i)=>`<g><circle cx="${100+i%3*285}" cy="${baseHeight+22+Math.floor(i/3)*24}" r="5" fill="${palette[groups[options.colorBy].indexOf(g.value)%palette.length]}"/><text x="${113+i%3*285}" y="${baseHeight+26+Math.floor(i/3)*24}" class="plot-tick">${esc(t(g.value))} (${g.count})</text></g>`).join(''));download('<?xml version="1.0" encoding="UTF-8"?>\n'+svg.outerHTML,'image/svg+xml;charset=utf-8',getLanguage()==='en'?'Actuator_Performance.svg':'电机性能对比.svg');}
 return {render,refreshLanguage(){if(root?.isConnected)render(root,records);}};
}
